-- Adds a publish gate to graphic_posts, separate from `posted` (social-media
-- tracking). A graphic is visible to non-admins only once its row here has
-- published = true. Existing registry graphics (Data Explorer datasets and
-- study graphics) were seeded published = true via a one-time INSERT ...
-- ON CONFLICT generated by scripts/print-published-seed.ts, run once against
-- production right after this migration - see that script for the exact
-- statement. New graphics added to the code registries afterward start
-- unpublished (no row) until an admin publishes them from the site.
alter table public.graphic_posts
  add column if not exists published boolean not null default false;
